// Lissajous Specimen

const NUM_POINTS = 128; // 8 corners + 120 Lissajous points
const BOX_THICKNESS = 2;
const END_THICKNESS = 10;
const CUBE_SIZE = 500;
const SEGMENTS = 7;

// Lissajous parameters
const FREQ_X = 3;
const FREQ_Y = 2;
const FREQ_Z = 5;
const PHASE = Math.PI / 4;

function lissajousPoint(t, scale) {
  const x = sin(FREQ_X * t + PHASE) * scale;
  const y = sin(FREQ_Y * t) * scale;
  const z = sin(FREQ_Z * t) * scale;
  return createVector(x, y, z);
}

const points = [];
const edges = [];

function setup() {
  createCanvas(800, 800, WEBGL);
  perspective(PI / 3, width / height, 0.1, 10000);

  // 1. Add 8 corner points
  const bipolar = [-1, 1];
  for (const x of bipolar) {
    for (const y of bipolar) {
      for (const z of bipolar) {
        const v = createVector(x, y, z).mult(CUBE_SIZE / 2);
        points.push(v);
      }
    }
  }

  // 2. Add points along a 3D Lissajous curve
  const count = NUM_POINTS - 8;
  for (let i = 0; i < count; i++) {
    const t = map(i, 0, count, 0, TWO_PI);
    points.push(lissajousPoint(t, CUBE_SIZE * 0.45));
  }

  buildGabrielGraph();
}

function draw() {
  background(255);
  orbitControl();
  rotateY(frameCount * -0.005);

  // --- Guide Box ---
  noFill();
  stroke(0); 
  strokeWeight(10); 
  box(CUBE_SIZE);

  // --- Edges ---
  fill(0);
  noStroke();

  for (const e of edges) {
    drawTaperedEdge(e.a, e.b);
  }
}

function buildGabrielGraph() {
  for (let i = 0; i < points.length; i++) {
    for (let j = i + 1; j < points.length; j++) {
      const a = points[i];
      const b = points[j];
      const mid = p5.Vector.add(a, b).mult(0.5);
      const radiusSq = p5.Vector.sub(a, mid).magSq();

      let ok = true;
      for (let k = 0; k < points.length; k++) {
        if (k === i || k === j) continue;
        const distSq = p5.Vector.sub(points[k], mid).magSq();
        if (distSq < radiusSq - 0.1) {
          ok = false;
          break;
        }
      }
      if (ok) edges.push({ a, b });
    }
  }
}

function drawTaperedEdge(p1, p2) {
  const dir = p5.Vector.sub(p2, p1);
  const len = dir.mag();

  const angleY = atan2(dir.x, dir.z);
  const angleX = acos(constrain(dir.y / len, -1, 1));

  for (let i = 0; i < SEGMENTS; i++) {
    const tStart = map(i, 0, SEGMENTS, -1, 1);
    const tEnd = map(i + 1, 0, SEGMENTS, -1, 1);
    const tMid = (tStart + tEnd) / 2;

    const segLen = len / SEGMENTS;
    const segMid = p5.Vector.lerp(p1, p2, (i + 0.5) / SEGMENTS);

    push();
    translate(segMid.x, segMid.y, segMid.z);
    rotateY(angleY);
    rotateX(angleX);
    cylinder(currentThickness(tMid), segLen + 0.5);
    pop();
  }
}

function currentThickness(t) {
  return (BOX_THICKNESS + (END_THICKNESS - BOX_THICKNESS) * (t * t)) / 2;
}


